with tempfile.TemporaryDirectory(prefix="codex-ab-session-observer-") as temporary:
    scratch=pathlib.Path(temporary)
    source=scratch/"probe_test.go"; source.write_text(GO_SOURCE)
    target=pathlib.Path.cwd()/"modules/threadcontrol/control"/f"zz_frozen_observation_{uuid.uuid4().hex}_test.go"
    if target.exists() or target.is_symlink(): raise RuntimeError("observer overlay target already exists")
    overlay=scratch/"overlay.json"; overlay.write_text(json.dumps({"Replace":{str(target):str(source)}}))
    environment=os.environ.copy()
    environment.update(GOFLAGS="-mod=readonly",CODEX_AB_SESSION_CASE=sys.argv[1],XDG_STATE_HOME=str(scratch/"state"),XDG_RUNTIME_DIR=str(scratch/"runtime"),MEKUGI_RUNTIME_DIR=str(scratch/"mekugi"),MEKUGI_TEST_CLAUDE_NATIVE="0",MEKUGI_TEST_WEBUI_BROWSER="0")
    result=subprocess.run(["go","test","-json","-count=1","-timeout=90s","-overlay",str(overlay),"./modules/threadcontrol/control","-run","^TestFrozenSessionObservation$"],env=environment,text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    values=[]
    for line in result.stdout.splitlines():
        try: row=json.loads(line)
        except ValueError: continue
        output=row.get("Output","")
        if output.startswith("FROZEN_OBSERVATION "): values.append(json.loads(output[len("FROZEN_OBSERVATION "):]))
    if result.returncode or len(values)!=1:
        sys.stderr.write(result.stderr+result.stdout)
        sys.exit(result.returncode or 1)
    print(json.dumps(values[0],sort_keys=True))

